    const map=page.maps.get(active);if(map&&!map.loading){const count=arr(map.raw_records||map.records||map.record_map).length,eventCount=current?.session_artifact?.events?.length||0,callCount=arr(current?.nodes).filter(n=>n.kind==='call').length;$('.showcase-source-line').append(el('strong','showcase-counts',`${count} 条原始记录 → ${eventCount} 个展示事件 · ${callCount} 次调用`));}
    const bar=$('.showcase-role-bar');bar.replaceChildren();
