      const original=details('查看这条原始记录',[note('展开后读取已保存的输入，不会调用模型。')]);let fetched=false;original.addEventListener('toggle',async()=>{if(!original.open||fetched)return;fetched=true;const body=original.querySelector('.analysis-details-body');try{if(!page.originals.has(id))page.originals.set(id,await request('/api/safety/showcase/cases/'+encodeURIComponent(id)+'/source'));const response=page.originals.get(id),source=response.source||response;const found=arr(source.session?.official_export?.events).find(e=>e.seq===r.original_seq);body.replaceChildren(code(found||{notice:'这条来源没有可直接对应的 official_export 记录；请核对完整输入。',mapping:r}));}catch(error){showError(body,error);fetched=false;}});entry.append(original);box.append(entry);
