    box.append(fields([['精确命中',value.expected_count?`${value.exact_hits??0} / ${value.expected_count} 项`:'原始对照，无预设注入风险'],['额外风险判断',arr(value.extra_findings).length],['缺证却判确定',value.overconfident_count??'未评估']]));
